with attendu as (select '{"colonnes": {"music_questionnaires": ["id:uuid:true", "order_id:uuid:true", "responses:jsonb:true", "form_version:text:true", "draft_updated_at:timestamp with time zone:true", "submitted_at:timestamp with time zone:false", "consent_at:timestamp with time zone:false", "consent_version:text:false", "created_at:timestamp with time zone:true", "updated_at:timestamp with time zone:true"]}, "contraintes": {"music_questionnaires": ["music_questionnaires_consent_version_format:c", "music_questionnaires_consentement_complet:c", "music_questionnaires_envoi_avec_consentement:c", "music_questionnaires_order_id_fkey:f:music_orders:ondelete=c", "music_questionnaires_order_id_key:u", "music_questionnaires_pkey:p", "music_questionnaires_responses_objet:c", "music_questionnaires_responses_taille:c", "music_questionnaires_version:c"]}, "fonctions": {"music_questionnaire_brouillon(text,jsonb)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "8404a7a6d9c3a684b8958b0f8676470d", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}, "music_questionnaire_charger(text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "09ca06757dac0a88be7de29d19eca552", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "s"}, "music_questionnaire_envoyer(text,jsonb,text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "8fbb25b37d48748bacc42f1ae20c33e2", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}}, "index": {"music_questionnaires": ["music_questionnaires_order_id_key:unique=true", "music_questionnaires_pkey:unique=true"]}, "policies": 0, "privileges_hors_proprietaire": {"music_questionnaires": []}, "proprietaires": {"music_questionnaires": "postgres"}, "rls": {"music_questionnaires": true}, "sequences": {}, "tables_presentes": ["music_questionnaires"], "triggers": 0}'::jsonb as e),
     reel as (
    select jsonb_build_object(
      'tables_presentes', (select coalesce(jsonb_agg(relname order by relname), '[]') from pg_class where relnamespace = 'public'::regnamespace and relkind = 'r' and relname = any(array['music_questionnaires']::text[])),
      'proprietaires', (select coalesce(jsonb_object_agg(relname, pg_get_userbyid(relowner)), '{}') from pg_class where relnamespace = 'public'::regnamespace and relname = any(array['music_questionnaires']::text[] || array['__aucune__']::text[])),
      'colonnes', (select coalesce(jsonb_object_agg(c.relname, (select jsonb_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull::text order by a.attnum) from pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped)), '{}')
                   from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_questionnaires']::text[])),
      'contraintes', (select coalesce(jsonb_object_agg(c.relname, (select jsonb_agg(k.conname || ':' || k.contype::text || case when k.contype = 'f' then ':' || k.confrelid::regclass::text || ':ondelete=' || k.confdeltype::text else '' end order by k.conname) from pg_constraint k where k.conrelid = c.oid and k.contype <> 'n')), '{}')
                      from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_questionnaires']::text[])),
      'index', (select coalesce(jsonb_object_agg(c.relname, (select coalesce(jsonb_agg(i.indexrelid::regclass::text || ':unique=' || i.indisunique::text order by i.indexrelid::regclass::text), '[]') from pg_index i where i.indrelid = c.oid)), '{}')
                from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_questionnaires']::text[])),
      'rls', (select coalesce(jsonb_object_agg(relname, relrowsecurity), '{}') from pg_class where relnamespace = 'public'::regnamespace and relkind = 'r' and relname = any(array['music_questionnaires']::text[])),
      'policies', (select count(*) from pg_policies where schemaname = 'public' and tablename = any(array['music_questionnaires']::text[])),
      'triggers', (select count(*) from pg_trigger t join pg_class c on c.oid = t.tgrelid where not t.tgisinternal and c.relnamespace = 'public'::regnamespace and c.relname = any(array['music_questionnaires']::text[])),
      'privileges_hors_proprietaire', (select coalesce(jsonb_object_agg(c.relname, (select coalesce(jsonb_agg(distinct case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end || ':' || x.privilege_type), '[]') from aclexplode(c.relacl) x where x.grantee <> c.relowner)), '{}')
                                       from pg_class c where c.relnamespace = 'public'::regnamespace and c.relname = any(array['music_questionnaires']::text[] || array['__aucune__']::text[])),
      'sequences', (select coalesce(jsonb_object_agg(s.sequencename, jsonb_build_object('type', s.data_type::text, 'debut', s.start_value, 'min', s.min_value, 'max', s.max_value, 'pas', s.increment_by, 'cycle', s.cycle)), '{}') from pg_sequences s where s.schemaname = 'public' and s.sequencename = any(array['__aucune__']::text[])),
      'fonctions', (select coalesce(jsonb_object_agg(p.oid::regprocedure::text, jsonb_build_object(
                       'md5_corps', md5(p.prosrc), 'security_definer', p.prosecdef, 'config', to_jsonb(p.proconfig), 'volatilite', p.provolatile::text,
                       'retour', format_type(p.prorettype, null), 'proprietaire', pg_get_userbyid(p.proowner),
                       'execute', (select coalesce(jsonb_agg(case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end order by case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end), '[]') from aclexplode(p.proacl) x where x.privilege_type = 'EXECUTE' and x.grantee <> p.proowner))), '{}')
                    from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any(array['music_questionnaire_charger','music_questionnaire_brouillon','music_questionnaire_envoyer']::text[]))
    ) as r)
select jsonb_pretty(jsonb_build_object(
  'migration', '021',
  'conforme', (select r from reel) = (select e from attendu),
  'sections_differentes', (select coalesce(jsonb_agg(k), '[]') from jsonb_object_keys((select e from attendu)) k where (select e from attendu)->k is distinct from (select r from reel)->k),
      'table_vide', (select count(*) = 0 from public.music_questionnaires),
      'fk_commande_cascade', exists (select 1 from pg_constraint where conrelid = 'public.music_questionnaires'::regclass and contype = 'f' and confrelid = 'public.music_orders'::regclass and confdeltype = 'c'),
      'envoi_exige_consentement', exists (select 1 from pg_constraint where conname = 'music_questionnaires_envoi_avec_consentement'),
      'sonde_charger_lien_inconnu', public.music_questionnaire_charger(repeat('0', 64))->>'error' = 'LIEN_INVALIDE',
      'sonde_charger_crm_seul', public.music_questionnaire_charger('CRM-00005')->>'error' = 'LIEN_INVALIDE',
      'objets_020_intacts', to_regclass('public.music_orders') is not null and to_regclass('public.music_order_ref_seq') is not null
)) as postcheck_021;
